import os
import torch
import random
import numpy as np


class Config:
    # ==========================================
    # Path Configuration
    # ==========================================
    # Root directories
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working"

    # Specific Input Paths
    TRAIN_DIR = os.path.join(INPUT_DIR, "train")
    TEST_DIR = os.path.join(INPUT_DIR, "test")
    SAMPLE_SUBMISSION_PATH = os.path.join(INPUT_DIR, "sample_submission.csv")

    # Metadata Paths (Generated by the provided script)
    TRAIN_METADATA_PATH = os.path.join(METADATA_DIR, "train_metadata.csv")
    VAL_METADATA_PATH = os.path.join(METADATA_DIR, "val_metadata.csv")
    TEST_METADATA_PATH = os.path.join(METADATA_DIR, "test_metadata.csv")

    # Output/Working Paths
    # We create a specific subdirectory for this idea/experiment
    EXPERIMENT_NAME = "idea_2"
    CACHE_DIR = os.path.join(WORKING_DIR, EXPERIMENT_NAME)

    # Model Checkpoint Path
    MODEL_PATH = os.path.join(CACHE_DIR, "best_model.pth")

    # Submission Path
    # Ensuring the submission directory exists is handled in inference
    SUBMISSION_DIR = "./submission"
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # Data Hyperparameters
    # ==========================================
    IMG_SIZE = 224  # Input resolution (224x224)
    NUM_CHANNELS = 3  # 3 Channels: FLAIR, T1wCE, T2w
    SLICING_METHOD = "middle"  # Strategy to select 2D slice

    # Normalization parameters (approximate for MRI if needed, or use simple min-max)
    USE_ALBUMENTATIONS = True

    # ==========================================
    # Model Hyperparameters
    # ==========================================
    BACKBONE = "efficientnet_b0"  # Lightweight and effective
    PRETRAINED = True
    NUM_CLASSES = 1  # Binary classification (MGMT value)
    DROPOUT_RATE = 0.2

    # ==========================================
    # Training Hyperparameters
    # ==========================================
    SEED = 42
    BATCH_SIZE = 32
    EPOCHS = 15
    LEARNING_RATE = 1e-4
    WEIGHT_DECAY = 1e-4
    PATIENCE = 5  # Early stopping patience

    # Compute settings
    NUM_WORKERS = 4  # Adjust based on vCPUs (12 avail)
    DEVICE = "cuda" if torch.cuda.is_available() else "cpu"

    # Debugging / Development
    DEBUG = False  # Set to True to run on a small subset
    DEBUG_SUBSET_SIZE = 50  # Number of samples to use in debug mode

    @classmethod
    def setup(cls):
        """
        Creates necessary output directories.
        """
        os.makedirs(cls.CACHE_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)

    @classmethod
    def set_seed(cls, seed=None):
        """
        Sets the random seed for reproducibility.
        """
        if seed is None:
            seed = cls.SEED

        random.seed(seed)
        np.random.seed(seed)
        torch.manual_seed(seed)
        torch.cuda.manual_seed(seed)
        torch.cuda.manual_seed_all(seed)

        # Ensure deterministic behavior for cuDNN
        torch.backends.cudnn.deterministic = True
        torch.backends.cudnn.benchmark = False
